using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class FinalEntryInspect {public static string Read(){var map=SceneManager.GetActiveScene().GetRootGameObjects().Single(g=>g.name=="MyeongjiMap");var rows=JObject.Parse(File.ReadAllText("Docs/MapLayout/Myeongji/ground_floor_final_inspect.json"))["result"];var result=new List<object>();foreach(var row in rows){string id=(string)row["id"];if(new[]{"G02","G04","H01"}.Contains(id))continue;int rot=(int)row["rot"];var n=rot==270?Vector3.left:rot==90?Vector3.right:Vector3.back;var u=Mathf.Abs(n.z)>.5?Vector3.right:Vector3.forward;var r=map.GetComponentsInChildren<MeshRenderer>().Single(v=>v.name=="AB01_"+id+".001");var m=r.GetComponent<MeshFilter>().sharedMesh;var vs=m.vertices.Select(p=>r.transform.TransformPoint(p)).ToArray();var groups=new List<object>();for(int sub=0;sub<m.subMeshCount;sub++){string mat=r.sharedMaterials[sub].name;if(!mat.Contains("Glass")&&!mat.Contains("Frame")&&!mat.Contains("Trim"))continue;var ts=m.GetTriangles(sub);var polys=new List<List<Vector3>>();for(int i=0;i<ts.Length;i+=3){var a=vs[ts[i]];var b=vs[ts[i+1]];var c=vs[ts[i+2]];if(Mathf.Max(a.y,Mathf.Max(b.y,c.y))>3.16f||Vector3.Dot(Vector3.Cross(b-a,c-a).normalized,n)<.98f)continue;if(Vector3.Dot(a,n)<(float)row["edge"]-1.4f)continue;polys.Add(new List<Vector3>{a,b,c});}
while(polys.Count>0){var group=polys[0];polys.RemoveAt(0);bool found=true;while(found){found=false;for(int k=polys.Count-1;k>=0;k--)if(polys[k].Any(p=>group.Any(v=>(v-p).sqrMagnitude<1e-8f))){group.AddRange(polys[k]);polys.RemoveAt(k);found=true;}}float low=group.Min(p=>p.y),high=group.Max(p=>p.y);if(mat.Contains("Glass")||(low>2.3f&&high<2.7f))groups.Add(new{mat,lo=group.Min(p=>Vector3.Dot(p,u)),hi=group.Max(p=>Vector3.Dot(p,u)),bottom=low,top=high,plane=group.Average(p=>Vector3.Dot(p,n))});}}
result.Add(new{id,groups});}File.WriteAllText("Docs/MapLayout/Myeongji/final_entry_inspect.json",JsonConvert.SerializeObject(result,Formatting.Indented));return JsonConvert.SerializeObject(result);}}
